  <style>
    :root { --dark:#111318; --panel:#1b1e24; --line:#343941; --red:#f04438; --yellow:#ffd35b; --muted:#a9afb8; }
    * { box-sizing:border-box; }
    body { margin:0; font-family:'DM Sans',sans-serif; color:#f7f7f4; }
    .app-shell { width:100%; min-height:100%; background:radial-gradient(ellipse at 84% -8%,#4b2425 0%,transparent 38%),#111318; }
    .race-lines { background-image:repeating-linear-gradient(115deg,transparent 0,transparent 38px,rgba(255,255,255,.025) 39px,rgba(255,255,255,.025) 40px); }
    .eyebrow,.mono { font-family:'Space Mono',monospace; }
    .card { background:var(--panel); border:1px solid var(--line); border-radius:18px; }
    .chart-box { position:relative; height:260px; width:100%; }
    .field { width:100%; min-height:42px; border-radius:10px; border:1px solid #484d56; background:#242830; color:#fff; padding:8px 11px; color-scheme:dark; }
    .field:focus-visible,button:focus-visible { outline:3px solid var(--yellow); outline-offset:3px; }
    .metric { font-family:'Space Mono',monospace; font-weight:700; letter-spacing:-.055em; font-size:clamp(1.55rem,2.6vw,2.65rem); line-height:1.15; overflow-wrap:anywhere; }
    .checkers { height:9px; background:conic-gradient(#f4f3ed 25%,#23262c 0 50%,#f4f3ed 0 75%,#23262c 0) 0 0/18px 18px; opacity:.7; }
    canvas { max-width:100%; }
    @media(max-width:640px){ .chart-box {height:230px;} }
  </style>
