   <header class="w-full border-b border-white/10">
    <div class="max-w-[1500px] mx-auto px-5 sm:px-8 py-7 md:py-9">
     <div class="flex flex-wrap items-center gap-3 mb-4"><span data-template-id="header-badge" class="canva-tag eyebrow inline-block rounded-md px-3 py-1.5 text-xs font-bold tracking-wider" style="background: rgb(240, 68, 56); color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 15px;">RACE CONTROL / AKADEMIK</span> <span data-template-id="source-badge" class="canva-tag eyebrow text-xs tracking-wide" style="color: rgb(255, 211, 91); font-weight: 400; font-style: normal; font-size: 15px;">DATA_MENTAH_PELAJAR.XLSX · PAPARAN DEMO</span>
     </div>
     <h1 data-template-id="page-title" class="canva-text font-extrabold tracking-tight leading-tight max-w-4xl" style="color: rgb(255, 255, 255); font-weight: 800; font-style: normal; font-size: 48px;">Prestasi pelajar.
Di garis hadapan.</h1>
     <p data-template-id="page-subtitle" class="canva-text mt-3 max-w-3xl leading-relaxed" style="color: rgb(197, 200, 207); font-weight: 400; font-style: normal; font-size: 17px;">Paparan ringkas untuk melihat kedudukan kohort, kehadiran dan pencapaian akademik.</p>
    </div>
   </header>
   <main class="max-w-[1500px] mx-auto px-5 sm:px-8 py-7 md:py-9">
    <aside data-template-id="demo-notice" class="canva-banner rounded-xl border border-amber-400/40 px-4 py-3 mb-7" style="background: rgb(52, 45, 29);">
     <p data-template-id="demo-notice-text" class="canva-text leading-relaxed" style="color: rgb(255, 229, 170); font-weight: 400; font-style: normal; font-size: 14px;">Nota data: angka ringkasan awal mengikut maklumat yang diberikan. Rekod individu dan carta menggunakan data demonstrasi kerana kandungan baris fail Excel tidak dapat dibaca di sini; jangan gunakan carta sebagai dapatan rasmi daripada fail.</p>
    </aside>
    <section aria-labelledby="filters-heading" data-template-id="filter-panel" class="canva-panel card p-5 sm:p-6 mb-7" style="background: rgb(27, 30, 36);">
     <div class="flex flex-wrap items-center justify-between gap-3 mb-5">
      <div>
       <p data-template-id="filter-kicker" class="canva-text eyebrow uppercase tracking-widest mb-1" style="color: rgb(240, 68, 56); font-weight: 400; font-style: normal; font-size: 12px;">Pit wall / kawalan</p>
       <h2 id="filters-heading" data-template-id="filter-heading" class="canva-text font-bold" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 23px;">Tapis paparan</h2>
      </div><button id="reset" type="button" data-template-id="reset-button" class="canva-button rounded-lg px-4 py-2.5 font-bold transition hover:brightness-110" style="background: rgb(255, 211, 91); color: rgb(22, 24, 28); font-weight: 700; font-style: normal; font-size: 15px;">Set semula penapis</button>
     </div>
     <div class="grid sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-4">
      <div>
       <label data-template-id="semester-label" class="canva-text block text-sm mb-2 font-semibold" for="semester" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Semester</label><select class="field" id="semester"><option value="">Semua semester</option></select>
      </div>
      <div>
       <label data-template-id="program-label" class="canva-text block text-sm mb-2 font-semibold" for="program" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Program</label><select class="field" id="program"><option value="">Semua program</option></select>
      </div>
      <div>
       <label data-template-id="gender-label" class="canva-text block text-sm mb-2 font-semibold" for="gender" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Jantina</label><select class="field" id="gender"><option value="">Semua jantina</option></select>
      </div>
      <div>
       <label data-template-id="status-label" class="canva-text block text-sm mb-2 font-semibold" for="status" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Status BKPKK</label><select class="field" id="status"><option value="">Semua status</option></select>
      </div>
      <div>
       <label data-template-id="gpa-min-label" class="canva-text block text-sm mb-2 font-semibold" for="gpa-min" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">PNGK min.</label><input class="field" id="gpa-min" type="number" min="0" max="4" step="0.01" value="0">
      </div>
      <div>
       <label data-template-id="gpa-max-label" class="canva-text block text-sm mb-2 font-semibold" for="gpa-max" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">PNGK maks.</label><input class="field" id="gpa-max" type="number" min="0" max="4" step="0.01" value="4">
      </div>
      <div class="sm:col-span-2 lg:col-span-2 xl:col-span-1 grid grid-cols-2 gap-2">
       <div>
        <label data-template-id="attendance-min-label" class="canva-text block text-sm mb-2 font-semibold" for="attendance-min" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Hadir min. %</label><input class="field" id="attendance-min" type="number" min="0" max="100" step="1" value="0">
       </div>
       <div>
        <label data-template-id="attendance-max-label" class="canva-text block text-sm mb-2 font-semibold" for="attendance-max" style="color: rgb(231, 232, 234); font-weight: 400; font-style: normal; font-size: 15px;">Maks. %</label><input class="field" id="attendance-max" type="number" min="0" max="100" step="1" value="100">
       </div>
      </div>
     </div>
    </section>
    <section aria-labelledby="overview-heading">
     <div class="flex flex-wrap justify-between items-end gap-2 mb-4">
      <h2 id="overview-heading" data-template-id="overview-heading" class="canva-text font-bold" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 23px;">Papan pemuka utama</h2>
      <p id="result-count" class="mono text-sm text-[#ffd35b]" aria-live="polite"></p>
     </div>
     <div class="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-3 mb-8">
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#f04438]">
       <h3 data-template-id="students-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">Jumlah pelajar</h3>
       <p id="students-value" class="metric"></p>
      </article>
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#ffd35b]">
       <h3 data-template-id="attendance-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">Purata kehadiran</h3>
       <p id="attendance-value" class="metric"></p>
      </article>
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#64d7d0]">
       <h3 data-template-id="gpa-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">Purata PNGK</h3>
       <p id="gpa-value" class="metric"></p>
      </article>
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#9be39d]">
       <h3 data-template-id="passed-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">BKPKK · Lulus</h3>
       <p id="passed-value" class="metric"></p>
      </article>
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#f8ab73]">
       <h3 data-template-id="review-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">Dalam Semakan</h3>
       <p id="review-value" class="metric"></p>
      </article>
      <article class="card p-4 sm:p-5 border-t-[3px] border-t-[#f04438]">
       <h3 data-template-id="top-label" class="canva-text text-sm font-semibold mb-4" style="color: rgb(185, 190, 199); font-weight: 400; font-style: normal; font-size: 18px;">PNGK tertinggi</h3>
       <p id="top-value" class="text-xl font-extrabold leading-tight break-words"></p>
      </article>
     </div>
    </section>
    <section aria-labelledby="charts-heading">
     <div class="mb-4">
      <p data-template-id="charts-kicker" class="canva-text eyebrow uppercase tracking-widest mb-1" style="color: rgb(240, 68, 56); font-weight: 400; font-style: normal; font-size: 12px;">Telemetry / analisis</p>
      <h2 id="charts-heading" data-template-id="charts-heading" class="canva-text font-bold" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 23px;">Corak di sebalik angka</h2>
     </div>
     <p id="empty-message" class="hidden card p-5 mb-5 text-[#ffd35b]" role="status">Tiada pelajar sepadan dengan penapis ini. Laraskan julat atau set semula penapis.</p>
     <div class="grid lg:grid-cols-2 gap-4">
      <article class="card p-5">
       <h3 data-template-id="status-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">Status BKPKK</h3>
       <p data-template-id="status-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Agihan pelajar mengikut status</p>
       <div class="chart-box">
        <canvas id="status-chart" role="img" aria-label="Carta donat status BKPKK"></canvas>
       </div>
      </article>
      <article class="card p-5">
       <h3 data-template-id="semester-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">Pecahan kohort</h3>
       <p data-template-id="semester-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Bilangan pelajar mengikut semester</p>
       <div class="chart-box">
        <canvas id="semester-chart" role="img" aria-label="Carta bar bilangan pelajar mengikut semester"></canvas>
       </div>
      </article>
      <article class="card p-5">
       <h3 data-template-id="program-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">Prestasi program</h3>
       <p data-template-id="program-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Purata PNGK dan kehadiran mengikut program</p>
       <div class="chart-box">
        <canvas id="program-chart" role="img" aria-label="Carta perbandingan purata PNGK dan kehadiran mengikut program"></canvas>
       </div>
      </article>
      <article class="card p-5">
       <h3 data-template-id="gender-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">PNGK mengikut jantina</h3>
       <p data-template-id="gender-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Perbandingan purata bagi setiap semester</p>
       <div class="chart-box">
        <canvas id="gender-chart" role="img" aria-label="Carta purata PNGK mengikut jantina dan semester"></canvas>
       </div>
      </article>
      <article class="card p-5">
       <h3 data-template-id="scatter-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">Kehadiran × PNGK</h3>
       <p data-template-id="scatter-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Setiap titik mewakili seorang pelajar</p>
       <div class="chart-box">
        <canvas id="scatter-chart" role="img" aria-label="Carta serakan kehadiran berbanding PNGK pelajar"></canvas>
       </div>
      </article>
      <article class="card p-5">
       <h3 data-template-id="distribution-chart-title" class="canva-text font-bold mb-1" style="color: rgb(255, 255, 255); font-weight: 700; font-style: normal; font-size: 19px;">Taburan PNGK</h3>
       <p data-template-id="distribution-chart-caption" class="canva-text text-sm mb-5" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 14px;">Bilangan pelajar dalam setiap julat PNGK</p>
       <div class="chart-box">
        <canvas id="distribution-chart" role="img" aria-label="Histogram taburan PNGK"></canvas>
       </div>
      </article>
     </div>
    </section>
    <footer class="py-8">
     <p data-template-id="footer-note" class="canva-text text-sm" style="color: rgb(169, 175, 184); font-weight: 400; font-style: normal; font-size: 15px;">Dashboard pembentangan · Data carta demonstrasi, bukan pengesahan terhadap fail asal.</p>
    </footer>
   </main>
  </div>
  <script>
    // Rekod demonstrasi: jumlah dan ringkasan awal sejajar dengan angka yang dibekalkan, bukan kandungan fail.
    const programs = ['Teknologi Maklumat','Pengurusan','Kejuruteraan'];
    const students = Array.from({length:60}, (_,i) => ({
      name:`Demo Pelajar ${String(i+1).padStart(3,'0')}`,
      semester:`Semester ${(i%4)+1}`,
      program:programs[i%3],
      gender:i%2===0?'Perempuan':'Lelaki',
      status:i<12?'Lulus':i<19?'Dalam Semakan':'Belum Lulus',
      attendance:80+((i*7)%21)-10,
      gpa:i===22?3.91:Number((2.61+((i*11)%21-10)*0.065-1.30/59).toFixed(2))
    }));
    const ids=['semester','program','gender','status','gpa-min','gpa-max','attendance-min','attendance-max'];
    const $=id=>document.getElementById(id);
    const charts={};
    const colors={red:'#f04438',yellow:'#ffd35b',teal:'#64d7d0',green:'#9be39d',orange:'#f8ab73'};
    const axisColor='#b9bec7';
    Chart.defaults.color=axisColor;
    Chart.defaults.font.family="'DM Sans', sans-serif";
    Chart.defaults.plugins.legend.labels.usePointStyle=true;
    Chart.defaults.plugins.legend.labels.boxWidth=10;
    Chart.defaults.plugins.tooltip.backgroundColor='#0b0d11';
    const mean=(rows,key)=>rows.length?rows.reduce((sum,row)=>sum+row[key],0)/rows.length:0;
    const avg=(rows,key)=>rows.length?Number(mean(rows,key).toFixed(2)):0;
    const count=(rows,key,value)=>rows.filter(row=>row[key]===value).length;
    function fillSelect(id, values) {
      values.forEach(value=>{
        const option=document.createElement('option');
        option.value=value; option.textContent=value; $(id).appendChild(option);
      });
    }
    fillSelect('semester',[1,2,3,4].map(n=>`Semester ${n}`));
    fillSelect('program',programs);
    fillSelect('gender',['Perempuan','Lelaki']);
    fillSelect('status',['Lulus','Dalam Semakan','Belum Lulus']);
    function chart(id,type,data,options={}) {
      if(charts[id]) { charts[id].data=data; charts[id].options=options; charts[id].update(); return; }
      charts[id]=new Chart($(id),{type,data,options});
    }
    const common=(extra={})=>({
      responsive:true,maintainAspectRatio:false,
      plugins:{legend:{position:'bottom'},...extra.plugins},
      scales:extra.scales
    });
    const grid={color:'rgba(255,255,255,.085)'};
    const axis={grid,ticks:{color:axisColor}};
    function render() {
      const minG=Number($('gpa-min').value),maxG=Number($('gpa-max').value);
      const minA=Number($('attendance-min').value),maxA=Number($('attendance-max').value);
      const rows=students.filter(s=>
        (! $('semester').value || s.semester===$('semester').value) &&
        (! $('program').value || s.program===$('program').value) &&
        (! $('gender').value || s.gender===$('gender').value) &&
        (! $('status').value || s.status===$('status').value) &&
        s.gpa>=minG && s.gpa<=maxG && s.attendance>=minA && s.attendance<=maxA
      );
      const full=rows.length===students.length && ids.every(id=>['semester','program','gender','status'].includes(id)?!$(id).value:
        ({'gpa-min':'0','gpa-max':'4','attendance-min':'0','attendance-max':'100'})[id]===$(id in {'gpa-min':1,'gpa-max':1,'attendance-min':1,'attendance-max':1}?$(id).value:''));
      $('result-count').textContent=`${rows.length} / 60 PELAJAR DIPAPARKAN`;
      $('empty-message').classList.toggle('hidden',rows.length!==0);
      $('students-value').textContent=rows.length;
      $('attendance-value').textContent=rows.length?(full?'80%':`${Math.round(mean(rows,'attendance'))}%`):'—';
      $('gpa-value').textContent=rows.length?(full?'2.61':mean(rows,'gpa').toFixed(2)):'—';
      $('passed-value').textContent=rows.length?`${(count(rows,'status','Lulus')/rows.length*100).toFixed(1)}%`:'—';
      $('review-value').textContent=rows.length?`${(count(rows,'status','Dalam Semakan')/rows.length*100).toFixed(1)}%`:'—';
      const top=[...rows].sort((a,b)=>b.gpa-a.gpa)[0];
      $('top-value').textContent=top?top.name:'—';

      const statuses=['Lulus','Dalam Semakan','Belum Lulus'];
      chart('status-chart','doughnut',{labels:statuses,datasets:[{data:statuses.map(x=>count(rows,'status',x)),backgroundColor:[colors.green,colors.orange,colors.red],borderColor:'#1b1e24',borderWidth:4}]},
        common({plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>`${c.label}: ${c.raw} pelajar`}}},scales:undefined}));
      const semesters=[1,2,3,4].map(n=>`Semester ${n}`);
      chart('semester-chart','bar',{labels:semesters,datasets:[{label:'Pelajar',data:semesters.map(x=>count(rows,'semester',x)),backgroundColor:colors.red,borderRadius:6}]},
        common({scales:{x:{grid:{display:false}},y:{...axis,beginAtZero:true,ticks:{precision:0}}}}));
      chart('program-chart','bar',{labels:programs,datasets:[
        {label:'PNGK purata',data:programs.map(p=>avg(rows.filter(s=>s.program===p),'gpa')),backgroundColor:colors.teal,yAxisID:'gpa',borderRadius:5},
        {label:'Kehadiran %',data:programs.map(p=>avg(rows.filter(s=>s.program===p),'attendance')),backgroundColor:colors.yellow,yAxisID:'attendance',borderRadius:5}
      ]},common({scales:{x:{grid:{display:false},ticks:{maxRotation:25,minRotation:0}},gpa:{...axis,position:'left',min:0,max:4,title:{display:true,text:'PNGK'}},attendance:{position:'right',min:0,max:100,grid:{drawOnChartArea:false},title:{display:true,text:'Kehadiran %'}}}}));
      chart('gender-chart','bar',{labels:semesters,datasets:['Perempuan','Lelaki'].map((gender,i)=>({
        label:gender,data:semesters.map(sem=>avg(rows.filter(s=>s.gender===gender&&s.semester===sem),'gpa')),
        backgroundColor:i?colors.yellow:colors.red,borderRadius:5
      }))},common({scales:{x:{grid:{display:false}},y:{...axis,min:0,max:4,title:{display:true,text:'Purata PNGK'}}}}));
      chart('scatter-chart','scatter',{datasets:[{label:'Pelajar',data:rows.map(s=>({x:s.attendance,y:s.gpa,name:s.name,program:s.program})),backgroundColor:colors.teal,pointRadius:5,pointHoverRadius:8}]},
        common({plugins:{tooltip:{callbacks:{label:c=>`${c.raw.name} · ${c.raw.program}: ${c.raw.x}% hadir, PNGK ${c.raw.y.toFixed(2)}`}}},scales:{x:{...axis,min:0,max:100,title:{display:true,text:'Kehadiran (%)'}},y:{...axis,min:0,max:4,title:{display:true,text:'PNGK'}}}}));
      const bins=['0.00–0.99','1.00–1.99','2.00–2.49','2.50–2.99','3.00–3.49','3.50–4.00'];
      const histogram=[0,0,0,0,0,0];
      rows.forEach(s=>{histogram[s.gpa<1?0:s.gpa<2?1:s.gpa<2.5?2:s.gpa<3?3:s.gpa<3.5?4:5]++;});
      chart('distribution-chart','bar',{labels:bins,datasets:[{label:'Pelajar',data:histogram,backgroundColor:bins.map((_,i)=>i>=4?colors.yellow:colors.red),borderRadius:5}]},
        common({scales:{x:{grid:{display:false},ticks:{maxRotation:35}},y:{...axis,beginAtZero:true,ticks:{precision:0}}}}));
    }
    ids.forEach(id=>$(id).addEventListener(['semester','program','gender','status'].includes(id)?'change':'input',render));
    $('reset').addEventListener('click',()=>{
      ['semester','program','gender','status'].forEach(id=>$(id).value='');
      Object.entries({'gpa-min':'0','gpa-max':'4','attendance-min':'0','attendance-max':'100'}).forEach(([id,value])=>$(id).value=value);
      render();
    });
    render();
  </script>
 
</body></html>